const KEY="worldwise-progress-v1";
const defaults=()=>({completed:[],quizzes:{},streakDates:[],reflection:"",week:0});
let state;try{state={...defaults(),...JSON.parse(localStorage.getItem(KEY)||"{}")}}catch{state=defaults()}
let selected=0, activeWeek=0, pendingInstall=null;
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
function persist(){localStorage.setItem(KEY,JSON.stringify(state));renderHome();renderProgress()}
function streak(){let dates=new Set(state.streakDates);let d=new Date();if(!dates.has(dateKey(d)))d.setDate(d.getDate()-1);let n=0;while(dates.has(dateKey(d))){n++;d.setDate(d.getDate()-1)}return n}
function studied(){const k=dateKey();if(!state.streakDates.includes(k))state.streakDates.push(k);state.streakDates=state.streakDates.slice(-400);persist()}
function toast(msg){$("toast").textContent=msg;$("toast").classList.add("show");setTimeout(()=>$("toast").classList.remove("show"),2300)}
function nav(view){document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id===view));document.querySelectorAll(".nav").forEach(x=>x.classList.toggle("active",x.dataset.nav===view));window.scrollTo({top:0,behavior:"smooth"});if(view==="learn")renderCurriculum();if(view==="progressView")renderProgress()}
document.querySelectorAll("[data-nav]").forEach(b=>b.addEventListener("click",()=>nav(b.dataset.nav)));
function openLesson(id){selected=id;renderLesson();nav("lesson");studied()}
function renderHome(){const next=LESSONS.find(l=>!state.completed.includes(l.id))||LESSONS[0];$("count").textContent=state.completed.length;$("streak").textContent=streak();const qs=Object.values(state.quizzes);$("average").textContent=qs.length?Math.round(qs.reduce((a,q)=>a+q.score,0)/qs.length*100)+"%":"—";$("todayTitle").textContent=`Day ${next.id+1}: ${next.title}`;$("todayDesc").textContent=`Politics: ${next.politics}. General culture: ${next.culture}.`;$("progress").style.width=(state.completed.filter(id=>Math.floor(id/7)===next.week).length/7*100)+"%";$("progressLabel").textContent=`${state.completed.filter(id=>Math.floor(id/7)===next.week).length} of 7 lessons completed in ${next.weekTitle}`;$("continue").textContent=(state.completed.includes(next.id)?"Review lesson":"Start today's lesson")+" →";$("continue").onclick=()=>openLesson(next.id);$("nextLessons").innerHTML=LESSONS.filter(l=>l.id>=next.id).slice(0,3).map(l=>`<button class="row" data-id="${l.id}"><span class="num">${state.completed.includes(l.id)?"✓":l.id+1}</span><span class="rowcopy"><b>${esc(l.title)}</b><small>Week ${l.week+1} · ${esc(l.politics)}</small></span>→</button>`).join("");$("nextLessons").querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>openLesson(+b.dataset.id))}
function renderCurriculum(){$("weeks").innerHTML=Array.from({length:12},(_,i)=>`<button data-week="${i}" class="${activeWeek===i?"active":""}">Week ${i+1}</button>`).join("");$("weeks").querySelectorAll("[data-week]").forEach(b=>b.onclick=()=>{activeWeek=+b.dataset.week;renderCurriculum()});$("curriculum").innerHTML=`<h2>${esc(LESSONS[activeWeek*7].weekTitle)}</h2>`+LESSONS.filter(l=>l.week===activeWeek).map(l=>`<button class="row" data-id="${l.id}"><span class="num">${state.completed.includes(l.id)?"✓":l.day+1}</span><span class="rowcopy"><b>${esc(l.title)}</b><small>${esc(l.politics)} · ${esc(l.culture)}</small></span>→</button>`).join("");$("curriculum").querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>openLesson(+b.dataset.id))}
function renderLesson(){const l=LESSONS[selected];$("lessonContent").innerHTML=`<div class="lessonhead"><p class="eyebrow">WEEK ${l.week+1} · DAY ${l.day+1}</p><h1>${esc(l.title)}</h1><p>Politics: ${esc(l.politics)}<br>General culture: ${esc(l.culture)}</p></div><section class="lessonblock"><p class="eyebrow">POLITICS · 20 MINUTES</p><h2>${esc(l.politics)}</h2><p>${esc(l.intro)}</p><div class="key"><b>Key idea:</b> ${esc(l.body)}</div><h3>Think about it</h3><p>${esc(l.prompt)}</p></section><section class="lessonblock"><p class="eyebrow">GENERAL CULTURE · 20 MINUTES</p><h2>${esc(l.culture)}</h2><p>${esc(l.cultureBody)}</p><p><b>Active recall:</b> Close this lesson and explain one idea in your own words.</p></section><section class="lessonblock"><p class="eyebrow">CURRENT AFFAIRS · 10 MINUTES</p><h2>Connect it to today</h2><p>Read a story and note what happened, where, who is involved, why it matters and what remains uncertain.</p><p><a href="https://www.bbc.com/news" target="_blank" rel="noopener">BBC News ↗</a> · <a href="https://www.reuters.com/" target="_blank" rel="noopener">Reuters ↗</a></p></section><section class="lessonblock"><p class="eyebrow">RECALL · 10 MINUTES</p><h2>Test your understanding</h2><p>Your quiz result will be saved on this device.</p><button class="primary" id="startQuiz">Take lesson quiz →</button></section>`;$("startQuiz").onclick=renderQuiz}
function renderQuiz(){const l=LESSONS[selected];nav("quiz");const old=state.quizzes[l.id];$("quizContent").innerHTML=`<p class="eyebrow">LESSON CHECK</p><h1>${esc(l.title)}</h1><p class="muted">Choose the best answer.</p><form id="quizForm" class="card"><h2>${esc(l.prompt)}</h2>${l.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" required><span>${esc(o)}</span></label>`).join("")}<button class="primary" type="submit">Check answer</button><div id="feedback"></div></form>${old?`<p class="muted small">Previous best: ${Math.round(old.score*100)}%</p>`:""}`;$("quizForm").onsubmit=e=>{e.preventDefault();const val=+new FormData(e.target).get("answer");const correct=val===l.correct;const score=correct?1:0;state.quizzes[l.id]={score:Math.max(score,state.quizzes[l.id]?.score||0),date:dateKey()};state.quizHistory=state.quizHistory||[];state.quizHistory.push({id:l.id,score,date:new Date().toISOString()});if(correct&&!state.completed.includes(l.id))state.completed.push(l.id);studied();e.target.querySelectorAll("input").forEach(x=>x.disabled=true);e.target.querySelector('button[type="submit"]').disabled=true;$("feedback").innerHTML=`<div class="feedback ${correct?"good":"bad"}"><b>${correct?"Correct!":"Not quite."}</b> ${esc(l.explanation)}</div><button type="button" id="review" class="secondary">Review lesson</button> <button type="button" id="next" class="primary">${l.id<83?"Next lesson →":"View progress"}</button>`;$("review").onclick=()=>openLesson(l.id);$("next").onclick=()=>l.id<83?openLesson(l.id+1):nav("progressView")}}
function renderProgress(){const scores=Object.values(state.quizzes);$("pCount").textContent=state.completed.length;$("pAverage").textContent=scores.length?Math.round(scores.reduce((a,q)=>a+q.score,0)/scores.length*100)+"%":"—";$("pStreak").textContent=streak()+" days";if(document.activeElement!==$("reflection"))$("reflection").value=state.reflection||""}
$("saveReflection").onclick=()=>{state.reflection=$("reflection").value;persist();$("reflectStatus").textContent="Reflection saved on this device.";toast("Reflection saved")};
$("export").onclick=()=>{const a=document.createElement("a"),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));a.href=url;a.download="worldwise-progress-backup.json";a.click();URL.revokeObjectURL(url);$("backupStatus").textContent="Backup exported."};
$("import").onchange=async e=>{try{const x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x.completed)||!x.quizzes)throw 0;state={...defaults(),...x};persist();renderCurriculum();$("backupStatus").textContent="Backup imported."}catch{$("backupStatus").textContent="That file is not a valid WorldWise backup."}e.target.value=""};
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();pendingInstall=e;$("install").classList.remove("hidden")});$("install").onclick=async()=>{if(!pendingInstall){toast("Open your browser menu and choose Add to Home screen.");return}pendingInstall.prompt();await pendingInstall.userChoice;pendingInstall=null;$("install").classList.add("hidden")};
if("serviceWorker"in navigator&&location.protocol!=="file:")window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));
renderHome();renderCurriculum();renderProgress();
